package main

import (
 "context"
 "io"
 "net/http"
 "os"
 "strings"
 "testing"

 "go.opentelemetry.io/otel/exporters/otlp/otlptrace/otlptracehttp"
 "go.opentelemetry.io/otel/sdk/trace/tracetest"
)

type captureTransport struct { url string }
func (c *captureTransport) RoundTrip(r *http.Request) (*http.Response,error) {
 c.url=r.URL.String()
 return &http.Response{StatusCode:200,Header:http.Header{"Content-Type":[]string{"application/x-protobuf"}},Body:io.NopCloser(strings.NewReader("")),Request:r},nil
}

func TestSourceExporterDefaultsWithoutNetwork(t *testing.T) {
 for _,item:=range os.Environ(){key,_,_:=strings.Cut(item,"=");if strings.HasPrefix(key,"OTEL_"){value:=os.Getenv(key);t.Cleanup(func(){_ = os.Setenv(key,value)});_ = os.Unsetenv(key)}}
 sink:=tracetest.NewInMemoryExporter();provider:=newProvider(sink)
 _,span:=provider.Tracer("source-resource-probe").Start(context.Background(),"probe");span.End()
 spans:=sink.GetSpans();if len(spans)!=1||spans[0].Resource.Len()!=0{t.Fatal("expected explicit empty resource without operator values")}
 if err:=provider.Shutdown(context.Background());err!=nil{t.Fatal(err)}
 transport:=&captureTransport{}
 exporter,err:=otlptracehttp.New(context.Background(),otlptracehttp.WithHTTPClient(&http.Client{Transport:transport}));if err!=nil{t.Fatal(err)}
 exported:=newProvider(exporter)
 _,span=exported.Tracer("source-endpoint-probe").Start(context.Background(),"probe");span.End()
 if transport.url!="https://localhost:4318/v1/traces"{t.Fatalf("unexpected default URL: %s",transport.url)}
 if err:=exported.Shutdown(context.Background());err!=nil{t.Fatal(err)}
 t.Logf("Explicit source resource attributes without operator values: %d",spans[0].Resource.Len())
 t.Logf("Default OTLP request URL intercepted without network: %s",transport.url)
}
